export type QueryFreshness = 'loading' | 'unavailable' | 'stale' | 'ready';

export function queryFreshness(input: {
  isLoading: boolean;
  isError: boolean;
  hasData: boolean;
}): QueryFreshness {
  if (input.isError && !input.hasData) {
    return 'unavailable';
  }
  if (input.isLoading && !input.hasData) {
    return 'loading';
  }
  if (input.isError && input.hasData) {
    return 'stale';
  }
  return 'ready';
}
